#include "StdAfx.h"#include "KeybCOM.h"#include "PipeScreen.h"//#include "Utils.h"#include "YokoUSB.h"//extern CYokoUSB usb;//CPipeScreen::CPipeScreen(): CPipeSerS( "PipeScreen", 0x10000, 32 )// Данные экрана, m_pScreenBMP(NULL), m_dwSizeBMP(0)// Передаваемые данные, m_pZlibBMP (NULL), m_dwZlibBMP(0)  {  }CPipeScreen::~CPipeScreen(void)  {  if ( m_pScreenBMP )    delete [] m_pScreenBMP;  if ( m_pZlibBMP )    delete [] m_pZlibBMP;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~int CPipeScreen::Action()  {	DWORD dwWrite;  DWORD dwCode = 0;  DWORD dwRead = 0;  // Читаем запрос  ReadFile( m_hPipe, &dwCode, sizeof(DWORD), &dwRead, NULL);  if ( dwRead != sizeof(DWORD) )    return -1;  // Выполняем действие  LARGE_INTEGER fr,c0,c1,c2,c3;  QueryPerformanceFrequency(&fr);  QueryPerformanceCounter(&c0);  ScreenToBmp();  QueryPerformanceCounter(&c1);  DWORD destLen = Compress();  QueryPerformanceCounter(&c2);  //  // Отправляем ответ  //  // 1.Записываем длину передаваемых данных	BOOL fSuccess = WriteFile( m_hPipe, &destLen, sizeof(DWORD), &dwWrite, NULL);  if ( !fSuccess || dwWrite != sizeof(DWORD) )    return -1;  if ( destLen == 0 ) return 0;  //  // 2.Записываем размер в байтах передаваемого изображения	fSuccess = WriteFile( m_hPipe, &m_dwSizeBMP, sizeof(DWORD), &dwWrite, NULL);  if ( !fSuccess || dwWrite != sizeof(DWORD) )    return -1;	if (m_dwSizeBMP == 0 ) return 0;  //  // 3.Переда¸м сжатое изображение  fSuccess = WriteFile( m_hPipe, m_pZlibBMP, destLen, &dwWrite, NULL);  DWORD dwError = GetLastError();  if (! fSuccess || dwWrite != destLen )    return -1;  QueryPerformanceCounter(&c3);  //  CKeyboard::scr1 = ((c1.LowPart-c0.LowPart)*1000.)/fr.LowPart;  CKeyboard::scr2 = ((c2.LowPart-c1.LowPart)*1000.)/fr.LowPart;  CKeyboard::scr3 = ((c3.LowPart-c2.LowPart)*1000.)/fr.LowPart;  ::InvalidateRect( usb, NULL, TRUE );  //  return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~#include ".\..\Utils\Zlib\Zlib.h"//#pragma comment( lib, "../../../EXE/ZLib.lib")//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~DWORD CPipeScreen::Compress()  {  if ( m_dwZlibBMP < m_dwSizeBMP/2 )    {    if ( m_pZlibBMP )      delete [] m_pZlibBMP;    m_pZlibBMP = new char [m_dwSizeBMP/2];    m_dwZlibBMP = m_dwSizeBMP/2;    }  uLongf destLen = m_dwZlibBMP;  int nZlib = compress2((Bytef*)m_pZlibBMP,&destLen,(Bytef*)m_pScreenBMP, m_dwSizeBMP, 1 );//int nZlib = compress ((Bytef*)m_pZlibBMP,&destLen,(Bytef*)m_pScreenBMP, m_dwSizeBMP);  if ( nZlib != 0 )    return 0;  return destLen;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~DWORD CPipeScreen::SizeHeader(BITMAPINFOHEADER* bi)  {  DWORD qqSize = sizeof(BITMAPINFO);  DWORD dwSize = sizeof(BITMAPINFOHEADER);  dwSize += sizeof(RGBQUAD)*bi->biClrImportant;  //  if ( bi->biBitCount == 0x20 )    bi->biCompression = 0;  //if ( bi->biCompression == BI_BITFIELDS )  //  dwSize += sizeof(RGBQUAD);  return dwSize;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~char* CPipeScreen::ScreenToBmp()  {  //  HDC hDC = ::CreateDC( "DISPLAY", NULL, NULL, NULL );  if ( hDC != NULL )    {    int cx = ::GetSystemMetrics( SM_CXSCREEN );    int cy = ::GetSystemMetrics( SM_CYSCREEN );    HBITMAP hBitmap = ::CreateCompatibleBitmap( hDC, cx, cy );    if ( hBitmap != NULL  )      {      HDC hdc = ::CreateCompatibleDC( hDC );      if ( hdc != NULL )        {        HBITMAP hOld = (HBITMAP)::SelectObject( hdc, hBitmap );        ::BitBlt( hdc, 0, 0, cx, cy, hDC, 0, 0, SRCCOPY );        //        char szBuff[1000];        memset( szBuff, 0, sizeof( szBuff ) );        BITMAPINFOHEADER* bi = (BITMAPINFOHEADER*)szBuff;        memset( bi, 0, sizeof( BITMAPINFOHEADER ) );        bi->biSize = sizeof(BITMAPINFOHEADER);        int nHeader = ::GetDIBits( hdc, hBitmap, 0, cy, NULL, (BITMAPINFO*)bi, DIB_RGB_COLORS );        if ( nHeader != 0 )          {          DWORD dwHead = SizeHeader(bi);          // Ширина картинки в битах          DWORD dwWidth = bi->biWidth*bi->biPlanes*bi->biBitCount;          // Ширина картинки в байтах          dwWidth = ((dwWidth+31)/32)*4;          DWORD dwSize = bi->biHeight*dwWidth+dwHead;          if ( m_dwSizeBMP < dwSize )            {            if ( m_pScreenBMP )              delete [] m_pScreenBMP;            m_pScreenBMP = new char [dwSize];            m_dwSizeBMP  = dwSize;            }          //          if ( m_pScreenBMP != NULL )            {            int nLines = ::GetDIBits( hdc, hBitmap, 0, cy, m_pScreenBMP+dwHead, (BITMAPINFO*)bi, DIB_RGB_COLORS );            memcpy( m_pScreenBMP, bi, dwHead );            }          else            m_dwSizeBMP = 0;          }        //        ::SelectObject( hdc, hOld );        ::DeleteDC( hdc );        }      ::DeleteObject( hBitmap );      }    ::DeleteDC( hDC );    }  return m_pScreenBMP;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~